using UnityEngine;
namespace CosmicBlock.UI {
 public sealed class SettingsPopupLayout : MonoBehaviour {
  void LateUpdate()=>Apply();
  public void Apply(){var card=(RectTransform)transform;var area=(RectTransform)card.parent;float width=Mathf.Min(area.rect.width*.82f,area.rect.height*.76f/.90f);card.anchorMin=card.anchorMax=card.pivot=Vector2.one*.5f;card.anchoredPosition=Vector2.zero;card.sizeDelta=new Vector2(width,width*.90f);float q=width/440f;GetComponent<PopupTypography>()?.Apply(q);transform.Find("CosmicFrame").GetComponent<HomeQuitMeshGraphic>().Geometry(18*q,q);foreach(string path in new[]{"Close","AudioControls/BgmToggle","AudioControls/SfxToggle"})transform.Find(path).GetComponent<HomeQuitMeshGraphic>().Geometry(10*q,q);var slider=transform.Find("AudioControls/BgmVolume");slider.Find("Track").GetComponent<HomeQuitMeshGraphic>().Geometry(4*q,q);(slider.Find("FillArea/Fill")??slider.Find("Fill")).GetComponent<HomeQuitMeshGraphic>().Geometry(4*q,0);(slider.Find("HandleArea/Handle")??slider.Find("Handle")).GetComponent<HomeQuitMeshGraphic>().Geometry(13*q,q);((RectTransform)(slider.Find("HandleArea/Handle")??slider.Find("Handle"))).sizeDelta=Vector2.one*26*q;var dim=(RectTransform)area.Find("DimOverlay");var canvas=(RectTransform)GetComponentInParent<Canvas>().transform;var min=area.InverseTransformPoint(canvas.TransformPoint(canvas.rect.min));var max=area.InverseTransformPoint(canvas.TransformPoint(canvas.rect.max));dim.anchorMin=dim.anchorMax=dim.pivot=Vector2.one*.5f;dim.sizeDelta=new Vector2(max.x-min.x,max.y-min.y);dim.localPosition=(min+max)*.5f;}
 }
}
